import type { Config } from "tailwindcss";

/**
 * Design tokens live here, not scattered through components.
 *
 * The reference is a printed equity research note: laid paper, printing ink,
 * tabular serif figures, annotations in the margin. Not a terminal. A reader
 * should feel they are holding a document that someone took care over, and the
 * care should read as rigour rather than decoration.
 *
 * The palette still encodes provenance, which remains the core idea:
 *   - `fact`  (sepia)  = a number or string retrieved from a data provider
 *   - `infer` (slate)  = text generated by the model
 * The hues are archival rather than neon — ledger ink and a cool annotation
 * blue — so the distinction survives without the page shouting. Hue does the
 * semantic work; the serif figures do the aesthetic work.
 *
 * Token NAMES are unchanged from the terminal build on purpose. Every
 * component already references them, so the whole surface re-skins from this
 * one file without a single component edit.
 */
const config: Config = {
  content: ["./app/**/*.{ts,tsx}", "./components/**/*.{ts,tsx}"],
  theme: {
    extend: {
      colors: {
        term: {
          bg: "#EDEBE3", // laid paper — warm stone with a grey-green cast
          panel: "#F8F7F3", // a lighter sheet laid on the paper
          raised: "#FFFFFF", // hover + active surface
          line: "#DAD8CE", // hairline rules
          dim: "#767B73", // graphite — secondary text
          text: "#343A35", // body
          bright: "#1C211D", // ink — headings and figures
        },
        fact: "#6B5533", // retrieved data — archival ledger ink
        infer: "#4C6A72", // model-generated — annotation slate
        up: "#3C6B55", // verdigris
        down: "#8E3B32", // oxblood
      },
      fontFamily: {
        /**
         * `mono` is bound to the serif on purpose.
         *
         * Every figure in this app is already marked up as `font-mono
         * tabular-nums`, which is the correct semantic — these are columns of
         * numbers that must align. Pointing that token at a serif with real
         * tabular lining figures re-sets every number in the application as a
         * printed research note would, and costs no component changes.
         */
        mono: ["var(--font-figure)", "ui-serif", "Georgia", "serif"],
        serif: ["var(--font-figure)", "ui-serif", "Georgia", "serif"],
        sans: ["var(--font-ui)", "ui-sans-serif", "system-ui"],
      },
      fontSize: {
        // Small UI text. Tracking is near-neutral now: the old wide tracking
        // existed to support all-caps labels, and those are gone.
        "2xs": ["0.6875rem", { lineHeight: "1rem", letterSpacing: "0.01em" }],
        // Hero figures. Serif numerals carry size well, so these run large.
        figure: ["2.75rem", { lineHeight: "1.05", letterSpacing: "-0.02em" }],
        "figure-sm": ["1.5rem", { lineHeight: "1.15", letterSpacing: "-0.015em" }],
      },
      borderRadius: {
        // Two radii only. A sheet of paper and a chip are different objects and
        // should not share a corner.
        sheet: "3px",
        chip: "2px",
      },
      boxShadow: {
        // One shadow, used once: a sheet lifted a millimetre off the paper.
        // Deliberately not applied to every card — see globals.css.
        sheet: "0 1px 2px rgba(28, 33, 29, 0.04), 0 4px 14px -6px rgba(28, 33, 29, 0.08)",
      },
      spacing: {
        // Editorial rhythm: one generous step the layout can lean on.
        gutter: "1.75rem",
      },
      keyframes: {
        "fade-up": {
          from: { opacity: "0", transform: "translateY(4px)" },
          to: { opacity: "1", transform: "none" },
        },
        "pulse-line": {
          "0%,100%": { opacity: "0.3" },
          "50%": { opacity: "0.85" },
        },
      },
      animation: {
        "fade-up": "fade-up 260ms cubic-bezier(0.2, 0.6, 0.2, 1) both",
        "pulse-line": "pulse-line 1.6s ease-in-out infinite",
      },
    },
  },
  plugins: [],
};

export default config;
